/**
 * Raised when work is pointed at someone who is not a current member of the
 * organization: an assignee or a project lead who has left, was never invited,
 * or belongs to a different workspace.
 *
 * The check lives in the service layer (`assertCurrentMember`); the class sits
 * here so `toAppError()` can translate it without reaching into `server/`.
 */
export class NotCurrentMemberError extends Error {
  readonly code = "validation_failed" as const;

  constructor(
    readonly userId: string,
    readonly field: string,
  ) {
    super(`User ${userId} is not a current member of this organization.`);
    this.name = "NotCurrentMemberError";
  }
}

