function principalFor(userId: UserId): SessionPrincipal {
  return {
    userId,
    email: "someone@example.test",
    activeOrgId: null,
    expiresAt: new Date(Date.now() + 3_600_000).toISOString() as IsoTimestamp,
  };
}

async function memberIdOf(tenant: Tenant, userId: UserId): Promise<MemberId> {
  const member = await memberRepo.findMember(tenant.org.id, userId);
  if (!member) throw new Error("fixture member missing");
  return member.id;
}

async function removeViewer(tenant: Tenant): Promise<MemberId> {
  const memberId = await memberIdOf(tenant, tenant.userIds.viewer);
  await memberService.removeMember(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId,
  });
  return memberId;
}

describe("removed members", () => {
  it("cannot resolve an actor or switch into the organization", async () => {
    const tenant = await createTenant("removed-session", "growth");
    const principal = principalFor(tenant.userIds.viewer);

    await expect(resolveActorForOrg(principal, tenant.org.slug)).resolves.not.toBeNull();
    await removeViewer(tenant);

    await expect(resolveActorForOrg(principal, tenant.org.slug)).resolves.toBeNull();
    await expect(
      memberService.resolveActor(tenant.userIds.viewer, tenant.org.id),
    ).resolves.toBeNull();
    await expect(
      switchActiveOrg(principal, { orgId: tenant.org.id }),
    ).rejects.toThrow(/not a member/);
    await expect(orgRepo.listOrgsForUser(tenant.userIds.viewer)).resolves.toEqual([]);
  });

  it("keeps their memberships in other workspaces", async () => {
    const tenant = await createTenant("removed-other-a", "growth");
    const other = await createTenant("removed-other-b", "growth");
    await memberRepo.insertMember(other.org.id, tenant.userIds.viewer, "member", null);

    await removeViewer(tenant);

    const orgs = await orgRepo.listOrgsForUser(tenant.userIds.viewer);
    expect(orgs.map((org) => org.id)).toEqual([other.org.id]);
    await expect(
      memberService.resolveActor(tenant.userIds.viewer, other.org.id),
    ).resolves.not.toBeNull();
  });

  it("refuse a second removal or a role change as a conflict", async () => {
    const tenant = await createTenant("removed-conflict", "growth");
    const memberId = await removeViewer(tenant);
