      memberService.removeMember(tenant.actors.owner, { orgId: tenant.org.id, memberId }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId,
        role: "admin",
      }),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    off();

    expect(removed).toHaveLength(0);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(seats);
    const row = await memberRepo.findMemberById(tenant.org.id, memberId);
    expect(row?.role).toBe("viewer");
  });

  it("have their issues unassigned and their projects left without a lead", async () => {
    const tenant = await createTenant("removed-work", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, {
        assigneeId: tenant.userIds.viewer,
      }),
    );
    const led = await projectService.createProject(tenant.actors.owner, {
      orgId: tenant.org.id,
      name: "Led by viewer",
      slug: "led-by-viewer",
      key: "LED",
      description: null,
      visibility: "org",
      leadId: tenant.userIds.viewer,
      color: "#6366f1",
      targetDate: null,
    });

    await removeViewer(tenant);

    const after = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(after?.assigneeId).toBeNull();
    const project = await projectRepo.findProjectById(tenant.org.id, led.id);
    expect(project?.leadId).toBeNull();
    // Someone else's lead is left alone.
    const platform = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(platform?.leadId).toBe(tenant.userIds.owner);
  });

