async function inviteToken(
  tenant: Tenant,
  email: string,
  role: "member" | "admin",
  seed: string,
) {
  const token = seed.repeat(32).slice(0, 32);
  const invitation = await invitationRepo.insertInvitation(
    tenant.org.id,
    { orgId: tenant.org.id, email, role, expiresInDays: 14 },
    tenant.userIds.admin,
    hashToken(token),
  );
  return { token, invitation };
}

describe("inviting a former member back", () => {
  it("re-admits them on the membership they already had", async () => {
    const tenant = await createTenant("readmit", "growth");
    const before = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!before) throw new Error("fixture member missing");
    await memberRepo.touchLastSeen(
      tenant.org.id,
      tenant.userIds.viewer,
      "2026-01-01T00:00:00.000Z" as IsoTimestamp,
    );
    await removeViewer(tenant);
    const seatsWhileGone = await memberRepo.countActiveMembers(tenant.org.id);

    const { token, invitation } = await inviteToken(
      tenant,
      "viewer@readmit.test",
      "admin",
      "r",
    );

    const joined: unknown[] = [];
    const off = subscribe("member.joined", (payload) => {
      joined.push(payload);
    });
    const member = await invitationService.acceptInvitation(tenant.userIds.viewer, {
      token,
    });
    off();

    expect(member.id).toBe(before.id);
    expect(member.createdAt).toBe(before.createdAt);
    expect(member.lastSeenAt).toBe("2026-01-01T00:00:00.000Z");
    expect(member.status).toBe("active");
    expect(member.archivedAt).toBeNull();
    expect(member.role).toBe("admin");
    expect(member.invitedBy).toBe(tenant.userIds.admin);

    const used = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(used?.acceptedAt).not.toBeNull();
    expect(member.joinedAt).toBe(used?.acceptedAt);
    expect(used?.id).toBe(invitation.id);

    expect(joined).toHaveLength(1);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(
      seatsWhileGone + 1,
    );

    const page = await memberRepo.listMembers({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    expect(page.items.filter((item) => item.userId === tenant.userIds.viewer)).toHaveLength(1);

    await expect(
      memberService.resolveActor(tenant.userIds.viewer, tenant.org.id),
    ).resolves.toEqual({
      userId: tenant.userIds.viewer,
      orgId: tenant.org.id,
      role: "admin",
    });

    const rows = await notify(tenant.org.id, "issue_assigned", [tenant.userIds.viewer], {
      title: "t",
      body: "b",
      href: "/x",
      actorId: null,
    });
    expect(rows).toHaveLength(1);

    await expect(
      invitationService.acceptInvitation(tenant.userIds.viewer, { token }),
    ).rejects.toThrow(/already been accepted/);
  });

  it("uses the invitation up when a current member accepts it, changing nothing", async () => {
    const tenant = await createTenant("accept-current", "growth");
    const before = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    const seats = await memberRepo.countActiveMembers(tenant.org.id);
    const { token } = await inviteToken(tenant, "member@accept-current.test", "admin", "c");

    const joined: unknown[] = [];
    const off = subscribe("member.joined", (payload) => {
      joined.push(payload);
    });
    const member = await invitationService.acceptInvitation(tenant.userIds.member, {
      token,
    });
    off();

    expect(member).toEqual(before);
    expect(await memberRepo.findMember(tenant.org.id, tenant.userIds.member)).toEqual(before);
    expect(joined).toHaveLength(0);
    await expect(memberRepo.countActiveMembers(tenant.org.id)).resolves.toBe(seats);

    const used = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(used?.acceptedAt).not.toBeNull();
    await expect(
      invitationService.acceptInvitation(tenant.userIds.member, { token }),
    ).rejects.toThrow(/already been accepted/);
  });
});

