  it("cannot resolve an actor or switch into the organization", async () => {
    const tenant = await createTenant("removed-session", "growth");
    const principal = principalFor(tenant.userIds.viewer);

    await expect(resolveActorForOrg(principal, tenant.org.slug)).resolves.not.toBeNull();
    await removeViewer(tenant);

    await expect(resolveActorForOrg(principal, tenant.org.slug)).resolves.toBeNull();
    await expect(
      memberService.resolveActor(tenant.userIds.viewer, tenant.org.id),
    ).resolves.toBeNull();
    await expect(
