      inApp: true,
      email: true,
      digestOnly: true,
    });
    await expect(listDigestRecipients(tenant.org.id)).resolves.toEqual([
      tenant.userIds.viewer,
    ]);

    await removeViewer(tenant);

    await expect(listDigestRecipients(tenant.org.id)).resolves.toEqual([]);
    const now = new Date();
    await expect(
      buildDigest(
        tenant.org.id,
        tenant.userIds.viewer,
        new Date(now.getTime() - 3_600_000).toISOString() as IsoTimestamp,
        now.toISOString() as IsoTimestamp,
